package websocket

import "github.com/thrasher-corp/gocryptotrader/exchanges/subscription"

// SetSubscriptionFilter filters subscriptions generated by Connect and FlushChannels.
// Pass nil to remove the filter. Explicit subscriptions passed to SubscribeToChannels
// or ResubscribeToChannel bypass it. The manager holds its lock while running the
// filter, so the filter must avoid calling methods that acquire that lock.
func (m *Manager) SetSubscriptionFilter(filter subscription.FilterHook) {
	m.m.Lock()
	defer m.m.Unlock()
	m.subscriptionFilter = filter
}
